from ortools.sat.python import cp_model
import json

def main():
    T = list(range(1, 11))
    C = [
        (1, 2), (2, 3), (1, 3), (4, 5), (5, 6), (6, 7), (4, 7), (1, 4), (3, 6),
        (8, 1), (8, 5), (8, 9), (9, 2), (9, 7), (9, 10), (10, 3), (10, 6), (10, 4)
    ]

    K = list(range(1, len(T) + 1))

    model = cp_model.CpModel()

    x = {}
    for i in T:
        for k in K:
            x[(i, k)] = model.NewBoolVar(f"x_{i}_{k}")

    y = {}
    for k in K:
        y[k] = model.NewBoolVar(f"y_{k}")

    for i in T:
        model.Add(sum(x[(i, k)] for k in K) == 1)

    for (i, j) in C:
        for k in K:
            model.Add(x[(i, k)] + x[(j, k)] <= 1)

    for k in K:
        model.Add(y[k] <= sum(x[(i, k)] for i in T))

        model.Add(sum(x[(i, k)] for i in T) <= len(T) * y[k])

    model.Minimize(sum(y[k] for k in K))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 0

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        tower_frequencies = {}
        for i in T:
            for k in K:
                if solver.Value(x[(i, k)]) == 1:
                    tower_frequencies[i] = k
                    break

        num_frequencies = sum(solver.Value(y[k]) for k in K)

        tower_frequencies_list = [tower_frequencies[i] for i in range(1, 11)]

        print(json.dumps({
            "tower_frequencies": tower_frequencies_list,
            "num_frequencies": num_frequencies
        }))

    else:
        print(f"No solution found. Solver status: {solver.StatusName(status)}")

if __name__ == "__main__":
    main()
